use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use tempfile::NamedTempFile;

use crate::error::{StfuError, StfuResult};

pub const CONF_NAME: &str = "50-disable-mics.conf";

/// WirePlumber 0.5+ drop-in configuration rules disabling ALSA, BlueZ and generic/virtual audio inputs
pub const DROPIN_CONTENT: &str = r#"# STFU: Hardware kill switch for all audio capture nodes (PipeWire/WirePlumber)
# Auto-generated by stfu v0.2.0

# 1. ALSA hardware inputs (built-in microphones, USB interfaces, PCIe capture)
monitor.alsa.rules = [
  {
    matches = [
      {
        node.name = "~alsa_input.*"
      }
    ]
    actions = {
      update-props = {
        node.disabled = true
      }
    }
  }
]

# 2. Bluetooth / BlueZ inputs (Headsets, AirPods, HFP/HSP voice profiles)
monitor.bluez.rules = [
  {
    matches = [
      {
        node.name = "~bluez_input.*"
      }
    ]
    actions = {
      update-props = {
        node.disabled = true
      }
    }
  }
]

# 3. Virtual and miscellaneous audio capture sources
wireplumber.rules = [
  {
    matches = [
      {
        media.class = "Audio/Source"
      },
      {
        media.class = "Audio/Source/Virtual"
      }
    ]
    actions = {
      update-props = {
        node.disabled = true
      }
    }
  }
]
"#;

pub fn dropin_dir() -> StfuResult<PathBuf> {
    let cfg = match std::env::var_os("XDG_CONFIG_HOME") {
        Some(val) => PathBuf::from(val),
        None => {
            let home = std::env::var_os("HOME")
                .ok_or_else(|| StfuError::ConfigDirResolution("HOME environment variable is not set".into()))?;
            PathBuf::from(home).join(".config")
        }
    };
    Ok(cfg.join("wireplumber").join("wireplumber.conf.d"))
}

pub fn conf_file() -> StfuResult<PathBuf> {
    Ok(dropin_dir()?.join(CONF_NAME))
}

pub fn is_killswitch_active() -> StfuResult<bool> {
    Ok(conf_file()?.exists())
}

/// Atomically write configuration into destination directory
pub fn write_dropin_atomic(dir: &Path, filename: &str, content: &str) -> StfuResult<PathBuf> {
    fs::create_dir_all(dir).map_err(|e| StfuError::Io {
        path: dir.display().to_string(),
        source: e,
    })?;

    let mut temp_file = NamedTempFile::new_in(dir).map_err(StfuError::TempFile)?;
    temp_file.write_all(content.as_bytes()).map_err(|e| StfuError::Io {
        path: temp_file.path().display().to_string(),
        source: e,
    })?;
    temp_file.as_file().sync_all().map_err(|e| StfuError::Io {
        path: temp_file.path().display().to_string(),
        source: e,
    })?;

    let target_path = dir.join(filename);
    temp_file
        .persist(&target_path)
        .map_err(|e| StfuError::Persist(format!("Failed to persist to {}: {}", target_path.display(), e)))?;

    Ok(target_path)
}

/// Clean up obsolete .disabled or temporary files left by earlier runs or toggles
pub fn clean_stale_files(dir: &Path) -> StfuResult<usize> {
    if !dir.exists() {
        return Ok(0);
    }
    let mut removed_count = 0;
    let entries = fs::read_dir(dir).map_err(|e| StfuError::Io {
        path: dir.display().to_string(),
        source: e,
    })?;

    for entry in entries.flatten() {
        let name = entry.file_name();
        let name_str = name.to_string_lossy();
        if name_str.starts_with(&format!("{CONF_NAME}.disabled"))
            || (name_str.starts_with(".tmp") && name_str.ends_with(".conf"))
        {
            let path = entry.path();
            if fs::remove_file(&path).is_ok() {
                removed_count += 1;
            }
        }
    }

    Ok(removed_count)
}
